<?php
require __DIR__.'/../cms/config.php'; require_login();$u=current_user();$users=read_json('users');$messages=read_json('messages');$target=(int)($_GET['to']??0);
$allowed=array_values(array_filter($users,fn($x)=>(int)($x['id']??0)!==(int)$u['id']&&($x['active']??true)));
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$to=(int)$_POST['to'];$ok=false;foreach($allowed as $x)if((int)$x['id']===$to)$ok=true;if($ok){$messages[]=['id'=>next_id($messages),'from_user_id'=>(int)$u['id'],'to_user_id'=>$to,'subject'=>trim($_POST['subject']),'body'=>trim($_POST['body']),'created_at'=>date('c'),'read'=>false];write_json('messages',$messages);flash('Message sent.');}redirect('messages.php');}
$in=array_values(array_filter($messages,fn($m)=>(int)($m['to_user_id']??0)===(int)$u['id']));$out=array_values(array_filter($messages,fn($m)=>(int)($m['from_user_id']??0)===(int)$u['id']));
function uname8($users,$id){foreach($users as $x)if((int)$x['id']===(int)$id)return $x['name']??$x['username']??'User';return 'User';}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Messages — Ridgefield</title><link rel="stylesheet" href="../cms/cms.css"><style>.wrap{max-width:1100px;margin:auto;padding:28px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.card{border:1px solid #dde3dd;border-radius:14px;padding:20px}.msg{padding:12px;border-bottom:1px solid #ddd}.unread{font-weight:700}input,textarea,select{width:100%;box-sizing:border-box;margin:5px 0 12px}@media(max-width:800px){.grid{grid-template-columns:1fr}}</style><link rel="stylesheet" href="assets/dynamic-site.css">
</head><body class="rf-dynamic"><div class="wrap"><p><a href="index.php">← Portal</a></p><h1>Messages</h1><div class="grid"><div class="card"><h2>Send message</h2><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><label>Recipient<select name="to" required><option value="">Select</option><?php foreach($allowed as $x):?><option value="<?=$x['id']?>"><?=h(uname8($users,$x['id']))?> (<?=h($x['role']??'') ?>)</option><?php endforeach;?></select></label><label>Subject<input name="subject" required></label><label>Message<textarea name="body" rows="7" required></textarea></label><button>Send</button></form></div><div class="card"><h2>Inbox</h2><?php foreach(array_reverse($in) as $m):?><div class="msg <?=empty($m['read'])?'unread':''?>"><div><?=h($m['subject'])?></div><small>From <?=h(uname8($users,$m['from_user_id']))?> · <?=h($m['created_at'])?></small><p><?=nl2br(h($m['body']))?></p></div><?php endforeach;if(!$in):?><p>No messages.</p><?php endif;?></div></div><div class="card" style="margin-top:18px"><h2>Sent</h2><?php foreach(array_reverse($out) as $m):?><div class="msg"><strong><?=h($m['subject'])?></strong> · To <?=h(uname8($users,$m['to_user_id']))?><p><?=nl2br(h($m['body']))?></p></div><?php endforeach;?></div></div><script src="assets/dynamic-site.js"></script>
</body></html>